    public function __construct(private readonly KaitenMigrationRepository $repo, private readonly KaitenClient $client, private readonly KaitenCrawler $crawler, private readonly KaitenTargetWriter $writer) {}

    public function processJob(string $jobPublicId, ?string $leaseToken = null): void
    {
        $job=$this->repo->getJob($jobPublicId);if(!$job)return;$connection=$this->repo->getConnectionById((int)$job['connection_id']);if(!$connection)throw new RuntimeException('KAITEN_CONNECTION_NOT_FOUND');$token=EncryptionService::decrypt((string)($connection['access_token_encrypted']??''));if($token===null)throw new RuntimeException('KAITEN_CREDENTIAL_DECRYPT_FAILED');$this->client->setConnectionId((int)$connection['id']);$this->client->setBaseUrl((string)($connection['base_url']??''));
        $existing=json_decode((string)($job['last_source_cursor']??''),true);$resume=is_array($existing)&&($existing['phase']??'')==='import'&&$this->repo->itemCount((int)$job['id'])>0&&str_starts_with((string)($job['current_step']??''),'import_');$heartbeat=$leaseToken!==null?fn():bool=>$this->repo->heartbeat($jobPublicId,$leaseToken):null;
        if($resume)$crawl=['resumed'=>true,'warnings'=>[]];else{$this->repo->updateProgress($jobPublicId,'crawl',0,['message'=>'Loading Kaiten source graph'],$leaseToken);$crawl=$this->crawler->crawl($job,$token,$heartbeat);if($leaseToken!==null&&!$this->repo->heartbeat($jobPublicId,$leaseToken))throw new RuntimeException('KAITEN_JOB_LEASE_LOST');$this->repo->addLog((int)$job['id'],'info','crawl','Kaiten source graph loaded.',$crawl);if(($job['mode']??'import')!=='dry_run')$this->repo->updateCursor($jobPublicId,json_encode(['phase'=>'import','priority'=>0,'id'=>0],JSON_UNESCAPED_UNICODE),$leaseToken);}
        if(($job['mode']??'import')==='dry_run'){$summary=['crawled'=>$crawl,'items'=>$this->repo->itemCounts((int)$job['id'])];$this->repo->updateSummary($jobPublicId,$summary,$leaseToken);$this->repo->updateProgress($jobPublicId,'dry_run_complete',100,$summary,$leaseToken);$this->repo->updateJobStatus($jobPublicId,'completed_with_warnings',$leaseToken);return;}
        $actor=$this->repo->actor((int)$job['created_by_user_id']);$total=max(1,$this->repo->itemCount((int)$job['id']));$counts=$this->repo->itemCounts((int)$job['id']);$done=array_sum(array_intersect_key($counts,array_flip(['imported','updated','skipped','failed'])));$warnings=(array)($crawl['warnings']??[]);$cursor=$resume&&is_array($existing)?$existing:['phase'=>'import','priority'=>0,'id'=>0];$priority=(int)($cursor['priority']??0);$lastId=(int)($cursor['id']??0);
        while(($items=$this->repo->importItemsBatch((int)$job['id'],$priority,$lastId,250))!==[]){foreach($items as $item){if($leaseToken!==null&&!$this->repo->heartbeat($jobPublicId,$leaseToken))throw new RuntimeException('KAITEN_JOB_LEASE_LOST');$current=$this->repo->getJob($jobPublicId);$status=(string)($current['status']??'');if(in_array($status,['pausing','paused','cancelling','cancelled'],true)){if($status==='pausing')$this->repo->updateJobStatus($jobPublicId,'paused');if($status==='cancelling')$this->repo->updateJobStatus($jobPublicId,'cancelled');return;}
