                $done++;$priority=(int)($item['import_priority']??$priority);$lastId=(int)$item['id'];$this->repo->updateProgress($jobPublicId,'import_'.$sourceType,min(99,($done/$total)*100),['processed'=>$done,'total'=>$total,'warnings'=>count($warnings)],$leaseToken);
            }$this->repo->updateCursor($jobPublicId,json_encode(['phase'=>'import','priority'=>$priority,'id'=>$lastId],JSON_UNESCAPED_UNICODE),$leaseToken);
