        $job=$this->repo->beginRollback($jobPublicId);if(!$job)throw new RuntimeException('KAITEN_ROLLBACK_REQUIRES_TERMINAL_JOB');$lease=(string)($job['lease_token']??'');$cursor=json_decode((string)($job['last_source_cursor']??''),true);$rollbackPriority=is_array($cursor)?max(0,(int)($cursor['rollback_priority']??0)):0;$before=is_array($cursor)?max(1,(int)($cursor['before_id']??PHP_INT_MAX)):PHP_INT_MAX;$warnings=[];
        try{while(($items=$this->repo->rollbackItemsBatch((int)$job['id'],$rollbackPriority,$before,250))!==[]){foreach($items as $item){if(!$this->repo->heartbeat($jobPublicId,$lease))throw new RuntimeException('KAITEN_ROLLBACK_LEASE_LOST');if((int)($item['created_by_job']??0)!==1||empty($item['target_public_id']))continue;try{$type=(string)$item['target_type'];$serviceId=match($type){'project'=>'service.project','project_module'=>'service.project_module','task'=>'service.task','file'=>'service.file','status'=>'service.status','tag'=>'service.tag','comment'=>'service.comment',default=>''};if($serviceId==='')continue;$service=$this->writer->service($serviceId);$deleted=in_array($type,['status','tag'],true)?$service->delete((string)$item['target_public_id']):$service->delete((string)$item['target_public_id'],$actor);$deletedOk=is_array($deleted)?(bool)($deleted['ok']??false):$deleted===true;if(!$deletedOk)throw new RuntimeException('KAITEN_ROLLBACK_TARGET_NOT_DELETED');$this->repo->upsertItem((int)$job['id'],(string)$item['source_type'],(string)$item['source_id'],['status'=>'rolled_back']);$this->repo->markMappingRolledBack((int)$job['connection_id'],(string)(in_array((string)$item['source_type'],['subcard'],true)?'card':$item['source_type']),(string)$item['source_id']);}catch(\Throwable $e){$warnings[]=(string)$item['source_id'];$this->repo->upsertItem((int)$job['id'],(string)$item['source_type'],(string)$item['source_id'],['status'=>'rollback_failed','error_code'=>'ROLLBACK_FAILED','error_message'=>'Target could not be removed.']);$this->repo->addLog((int)$job['id'],'warning','rollback','Target item was not removed.',['source_id'=>$item['source_id'],'error_code'=>$e->getCode()?:'KAITEN_ROLLBACK_TARGET_NOT_DELETED']);}}
                if($warnings!==[])break;$lastItem=$items[count($items)-1];$rollbackPriority=(int)($lastItem['rollback_priority']??$rollbackPriority);$before=(int)$lastItem['id'];$this->repo->updateCursor($jobPublicId,json_encode(['phase'=>'rollback','rollback_priority'=>$rollbackPriority,'before_id'=>$before],JSON_UNESCAPED_UNICODE),$lease);}
            $this->repo->updateSummary($jobPublicId,['rollback_warnings'=>array_values(array_unique($warnings))],$lease);$this->repo->updateProgress($jobPublicId,'rolled_back',100,['warnings'=>count($warnings)],$lease);$this->repo->updateJobStatus($jobPublicId,$warnings===[]?'rolled_back':'rolled_back_with_warnings',$lease);$this->repo->releaseLease($jobPublicId,$lease);
        }catch(\Throwable $e){try{if($this->repo->ownsLease($jobPublicId,$lease)){$this->repo->updateJobStatus($jobPublicId,'rollback_failed',$lease);$this->repo->releaseLease($jobPublicId,$lease);}}catch(\Throwable){}throw $e;}
    }
